// frontend/src/pages/LobbyPage.jsx
import React, { useContext } from "react";
import { AuthContext } from "../auth/AuthContext";
import { useNavigate } from "react-router-dom";

export default function LobbyPage() {
  const { user, logout } = useContext(AuthContext);
  const navigate = useNavigate();

  const goToJoinRoom = () => {
    navigate("/");
  };

  return (
    <div
      style={{
        minHeight: "100vh",
        background: "linear-gradient(to bottom right, #e8fff3, #d4fce7)",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        padding: "30px"
      }}
    >
      <div
        style={{
          width: "480px",
          background: "#ffffff",
          padding: "35px",
          borderRadius: "16px",
          boxShadow: "0 4px 20px rgba(0,0,0,0.08)",
          textAlign: "center"
        }}
      >
        <h1 style={{ color: "#0f5132", marginBottom: "12px" }}>
          Welcome, {user?.name || "User"}!
        </h1>

        <p style={{ color: "#3d7a58", marginBottom: "25px" }}>
          What would you like to do today?
        </p>

        <button
          style={{
            background: "#1e8f55",
            width: "100%",
            padding: "12px",
            borderRadius: "8px",
            border: "none",
            color: "#fff",
            fontSize: "16px",
            cursor: "pointer"
          }}
          onClick={goToJoinRoom}
        >
          Join / Create Room
        </button>

        <button
          style={{
            background: "#fff",
            width: "100%",
            padding: "12px",
            borderRadius: "8px",
            border: "1px solid #1e8f55",
            color: "#1e8f55",
            fontSize: "16px",
            cursor: "pointer",
            marginTop: "14px"
          }}
          onClick={logout}
        >
          Logout
        </button>
      </div>
    </div>
  );
}
